BY_NAME={name:key for key,(names,_,_) in SPECS.items() for name in names}
AGGREGATES={'income','tax','non-tax','expenses-transfers','expenses','interest','transfers','provided','received','financing','external-financing','internal-financing','privatization'}
TOP={'income','expenses-transfers','eu','balance','financing'}

def structure(rows):
 out=[];section=None;group=None;direction=None
 for raw in rows:
  ident=BY_NAME.get(raw['line'],'unknown:'+raw['line']+':'+str(raw.get('order')))
  if ident in TOP:section=ident;group=None;direction=None;parent=None
  elif section=='income':
   if ident in ('tax','non-tax','grants'):parent=section;group=ident if ident!='grants' else None
   else:parent='income/'+(group or 'unknown')
  elif section=='expenses-transfers':
   if ident in ('expenses','transfers'):parent=section;group=ident;direction=None
   elif ident in ('provided','received'):parent=section+'/transfers';group='transfers';direction=ident
   elif group=='transfers':parent=section+'/transfers/'+(direction or 'unknown')
   elif ident in ('interest-external','interest-internal'):parent=section+'/expenses/interest'
   else:parent=section+'/expenses'
  elif section=='financing':
   if ident in ('external-financing','internal-financing','privatization'):parent=section;group=ident
   else:parent=section+'/'+(group or 'unknown')
  else:parent=section
  key=(parent+'/' if parent else '')+ident
  title=raw['line']
  if ident=='privatization':title='Приватизация, придобиване на дялове и акции, и възмездни средства (нето)'
  spec=SPECS.get(ident)
  out.append(dict(raw,key=key,parent=parent,ident=ident,depth=key.count('/'),summary=ident in TOP,aggregate=ident in AGGREGATES,display_line=title,description=spec[1] if spec else 'Източникът публикува този ред без проверено допълнително определение. Вижте оригиналния ресурс.',example=spec[2] if spec else 'За този непознат ред не предполагаме пример или съдържание.'))
 bykey={r['key']:r for r in out}
 if len(bykey)!=len(out):raise ValueError('Повтарящ се бюджетен ред в една и съща категория')
 for r in out:r['section']=bykey[r['parent']]['display_line'] if r['parent'] in bykey else None
 return out
